import { ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { MatExpansionModule } from '@angular/material/expansion';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { BadgeComponent } from '../../../../shared/components/badge/badge.component';
import { CommonModule } from '@angular/common';
import { FactTableComponent } from '../../../../shared/components/fact-table/fact-table.component';
import { WorkspaceService } from '../../../services/workspace/workspace.service';
import { contactCategory, FactfileRes, factissuelistRes, factlistRes, IssuecategoryRes } from '../../../interfaces/workspace.interface';
import { EmptyComponent } from '../../../../shared/components/empty/empty.component';
import { SkeletonComponent } from '../../../../shared/components/skeleton/skeleton.component';
import { Subject } from 'rxjs';
import { myTeamUsers, toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { finalFilterList } from '../../../../shared/interfaces/filter.interface';
import { CommonService } from '../../../../shared/services/common/common.service';
import { FactsheetService } from '../../../services/factsheet/factsheet.service';

@Component({
  selector: 'workspace-contacts',
  standalone: true,
  imports: [MatExpansionModule, IconComponent, FactTableComponent, BadgeComponent, CommonModule, EmptyComponent, SkeletonComponent],
  templateUrl: './workspace-contacts.component.html',
  styleUrl: './workspace-contacts.component.scss'
})
export class WorkspaceContactsComponent {

  @Input() tablecols: any;
  @Input() nCaseid: string;
  @Input() activetab: string;
  @Input() isWithContact: boolean = true;
  @Input() isWithoutContact: boolean = true;
  @Input() onWorkspaceEvent: Subject<toolEvents>;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  @Input() isCritical: boolean;
  @Input() isHeavily: boolean;

  List: contactCategory[] = [];
  loading: boolean = true;
  jFilter: finalFilterList[] = [];
  userList: myTeamUsers[] = [];
  withContactLength: number = 0;
  withOutContactLength: number = 0;
  constructor(private wsservice: WorkspaceService, private cdr: ChangeDetectorRef,
    private common: CommonService,
    private factsheetService: FactsheetService,
  ) { }

  ngOnInit() {
    this.getContactlist();
    if (this.onWorkspaceEvent) {
      this.onWorkspaceEvent.subscribe((e: toolEvents) => {
        if (e.event == 'FILTER') {
          this.jFilter = e.data;
          this.getContactlist();
        }
      });
    }
    // this.getteam_list();
  }


  ngOnChanges(changes: SimpleChanges): void {
    if (changes['isHeavily'] || changes['isCritical']) {
      this.sortfact()
    }
    this.cdr.detectChanges();
  }

  async getteam_list() {
    this.userList = await this.common.getMyTeamUsers(this.nCaseid);
  }


  async getContactlist() {
    this.loading = true;
    this.List = [];
    this.List = await this.wsservice.getContactlist(this.nCaseid, this.jFilter);
    this.getCount()
    this.loading = false;
    this.cdr.detectChanges();
  }

  getCount() {
    this.withOutContactLength = 0;
    this.withContactLength = 0;
    for (let c of this.List) {
      for (let x of c.contactls) {
        if (c.nCompanyid) {
          this.withContactLength += parseInt(x.nFCount)
        } else {
          this.withOutContactLength += parseInt(x.nFCount)
        }

      }

    }

    this.OnEvent.emit({ event: 'Length', data: [this.withContactLength ? this.withContactLength : 0, this.withOutContactLength ? this.withOutContactLength : 0] })

  }


  async getFactlist(x, nContactid, nIssueid) {
    if (nContactid && x.factlist && x.factlist.length) { return; }
    if (!x.isopened) { return; }
    x.loading = true;
    let res: factlistRes[] = await this.wsservice.getFactlist(this.nCaseid, nContactid, nIssueid, 'ALL', this.jFilter);
    x.loading = false;
    x.factlist = res.filter(e => e.cFType == 'F')//this.groupIssueCategory(res);
    x.quickfactlist = res.filter(e => e.cFType == 'FQ')//this.groupIssueCategory(res);

    // Normalized note sort key so Note column sorting works here as in Chronology
    const computeNoteSort = (f: factlistRes) => {
      const base = (f.cFact && f.cFact.trim().length)
        ? f.cFact
        : (Array.isArray(f.jTexts) && f.jTexts.length ? String(f.jTexts[0]) : '');
      f.noteSort = base || '';
    };
    x.factlist.forEach(computeNoteSort);
    x.quickfactlist.forEach(computeNoteSort);

    this.getIssuels(x, nContactid, nIssueid);
    this.getFactfile(x, nContactid, nIssueid);
    this.OnEvent.emit({ event: 'Length', data: [this.withContactLength ? this.withContactLength : 0, this.withOutContactLength ? this.withOutContactLength : 0] })
  }

  async getIssuels(x, nContactid: string, nIssueid: string) {
    const res: factissuelistRes[] = await this.wsservice.getFactIssuelist(this.nCaseid, nContactid, nIssueid, 'ALL', this.jFilter);
    
    // Load counts for all facts in parallel
    await Promise.all(x.factlist.map(async element => {
      let issues = res.filter(e => e.nFSid == element.nFSid);
      element.issues = issues;
      this.relavanceImpactFilter(element, issues);
      
      // Load contacts, tasks, and links counts in parallel
      const [contacts, tasks, links] = await Promise.all([
        this.wsservice.getFactContact(element.nFSid),
        this.wsservice.getFactTask(element.nFSid),
        this.factsheetService.getFactLinks<any>(element.nFSid)
      ]);
      
      element.nContactcount = Array.isArray(contacts) ? contacts.length : 0;
      element.nTaskcount = Array.isArray(tasks[0]) ? tasks[0].length : 0;
      element.nLinkscount = (links && Array.isArray(links.value)) ? links.value.length : 0;
    }));
    
    this.cdr.detectChanges();
  }


  relavanceImpactFilter(fact, issues) {
    if (issues.length) {
      let max = issues.reduce((prev, current) => (prev.nRelevanceseq > current.nRelevanceseq) ? prev : current);
      fact.nRelevancecount = issues.filter(e => e.nRelevanceid == max.nRelevanceid).length;
      fact.cRelevance = max.cRelevance;
    }
    if (issues.length) {
      let max = issues.reduce((prev, current) => (prev.nImpactseq > current.nImpactseq) ? prev : current);
      fact.nImpactcount = issues.filter(e => e.nImpactid == max.nImpactid).length;
      fact.nImpactid = max.nImpactid;
    }
    if (issues.length) {
      fact.issuesSort = issues.map(e => e.cIName || '').join(', ').trim();
    } else {
      fact.issuesSort = '';
    }
    // issues.forEach(element => {
    //   if (element.cRelevance == fact.cRelevance) {
    //     fact.nRelevancecount++;
    //   }
    //   if (element.nImpactid == fact.nImpactid) {
    //     fact.nImpactcount++;
    //   }
    // });
    return fact;

  }


  groupIssueCategory(issues) {
    let issuecategory: IssuecategoryRes[] = [];
    issues.forEach(element => {
      if (!issuecategory.length) {
        issuecategory.push({ nICid: element.nICid, cCategory: element.cCategory, sublist: [element] });
      } else {
        let index = issuecategory.findIndex(e => e.nICid == element.nICid);
        if (index > -1) {
          issuecategory[index].sublist.push(element);
        } else {
          issuecategory.push({ nICid: element.nICid, cCategory: element.cCategory, sublist: [element] });
        }
      }
    });
    return issuecategory;
  }

  async getFactfile(x, nContactid: string, nIssueid: string) {
    const res: FactfileRes[] = await this.wsservice.getFactfilelist(this.nCaseid, nContactid, nIssueid, 'ALL', this.jFilter);
    x.factlist.forEach(element => {
      let file: FactfileRes[] = res.filter(e => e.nFSid == element.nFSid);
      element.linkfile = file
    });
    this.cdr.detectChanges();
  }


  removeGroup(x) {
    x.isGrouping = false;
    x.groupinglist = [];

  }



  OnTableEvent(e, x) {
    if (e.event == 'SORT') {
      let col = e.data.col;
      let typ = e.data.col.typ == 'A' ? 'asc' : e.data.col.typ == 'D' ? 'desc' : 'G';
      if (typ == 'G') {
        x.isGrouping = true;
        x.groupinglist = [];
        if (col.clmn == 'R' || col.clmn == 'I') {
          for (let n of x.factlist) {
            var obj: any = {};
            var searchclm = '';
            if (col.clmn == 'R') {
              x.Groupby = 'Relevance';
              searchclm = 'nRelevanceid';

              for (let i of n.issues) {
                for (let issue of i.sublist) {
                  if (issue.nRelevanceid) {
                    obj = { id: issue.nRelevanceid, name: issue.cRelevance };
                    if (Object.keys(obj).length) {
                      var ins = x.groupinglist.findIndex(m => m.id == obj.id);
                      if (ins >= 0) {
                        if (x.groupinglist[ins]["factlist"].findIndex(m => m.nFSid == n.nFSid) == -1) {
                          x.groupinglist[ins]["factlist"].push(n);
                        }
                      } else {
                        x.groupinglist.push({ id: obj.id, name: obj.name, factlist: [n] });
                      }
                    }
                    // break;
                  }
                }
              }
            } else if (col.clmn == 'I') {
              x.Groupby = 'Impact';
              searchclm = 'nImpactid';
              for (let i of n.issues) {
                for (let issue of i.sublist) {
                  if (issue.nImpactid) {
                    obj = { id: issue.nImpactid, name: issue.cImpact };
                    if (Object.keys(obj).length) {
                      var ins = x.groupinglist.findIndex(m => m.id == obj.id);
                      if (ins >= 0) {
                        if (x.groupinglist[ins]["factlist"].findIndex(m => m.nFSid == n.nFSid) == -1) {
                          x.groupinglist[ins]["factlist"].push(n);
                        }
                      } else {
                        x.groupinglist.push({ id: obj.id, name: obj.name, factlist: [n] });
                      }
                    }
                    // break;
                  }
                }
              }
              // obj = n.nImpactid ? { id: n.nImpactid, name: n.cImpact, img: n.impactls[0]["cImpimg"] } : {};
            }
          }
        }
        else if (col.clmn == 'F') {
          x.Groupby = 'Level type';
          x.groupinglist = [{
            "id": 1,
            "name": "File level",
            "factlist": []
          }, {
            "id": 2,
            "name": "Text level",
            "factlist": []
          }, {
            "id": 3,
            "name": "Range level",
            "factlist": []
          }];
          for (let n of x.factlist) {
            try {
              if (n.jLinktype.type != 'F' && n.cType == 'M') {
                if (x.groupinglist[2]["factlist"].findIndex(m => m.nFSid == n.nFSid) == -1) {
                  x.groupinglist[2]["factlist"].push(n);
                }
              } else if (n.jLinktype?.type == 'F' && n.cType == 'M') {
                if (x.groupinglist[0]["factlist"].findIndex(m => m.nFSid == n.nFSid) == -1) {
                  x.groupinglist[0]["factlist"].push(n);
                }
              } else if (n.cType != 'M') {
                if (x.groupinglist[1]["factlist"].findIndex(m => m.nFSid == n.nFSid) == -1) {
                  x.groupinglist[1]["factlist"].push(n);
                }
              }
            } catch (error) { }
          }
        }
        if (!x.groupinglist.length) {
          x.groupFor = '';
          x.isGrouping = false;
        }
        if (col.clmn == 'F') {
          let isdata: boolean = false
          x.groupinglist.forEach(e => {
            if (e.factlist.length) {
              isdata = true
            }
          });
          x.isGrouping = isdata;
        }
        return;
      }
      const clmn = col.clmn == 'topimpact_ind' ? 'nImpactid' : col.clmn == 'toprelevance_ind' ? 'cRelevance' : col.clmn;
      x.factlist = x.factlist.sort((a, b) => {
        const aRaw = (a as any)[clmn];
        const bRaw = (b as any)[clmn];
        const aVal = aRaw === null || aRaw === undefined ? '' : String(aRaw);
        const bVal = bRaw === null || bRaw === undefined ? '' : String(bRaw);
        if (typ == 'asc') {
          return aVal.localeCompare(bVal);
        } else {
          return bVal.localeCompare(aVal);
        }
      });


    } else {
      this.OnEvent.emit(e);
    }
  }

  sortfact() {
    let ls = this.List.find(e => e.isopened)
    if(ls.factlist.length==0){return;}
    ls.factlist.sort((a, b) => {
      const aImpact = a?.issues[0]?.['nImpactseq'] ?? Number.MAX_SAFE_INTEGER;
      const bImpact = b?.issues[0]?.['nImpactseq'] ?? Number.MAX_SAFE_INTEGER;
      if (this.isHeavily) {
        return aImpact - bImpact;
      } else {
        return aImpact + bImpact;
      }
    });

    ls.factlist.sort((a, b) => {
      const aRelevance = a?.issues[0]?.['nRelevanceseq'] ?? Number.MAX_SAFE_INTEGER;
      const bRelevance = b?.issues[0]?.['nRelevanceseq'] ?? Number.MAX_SAFE_INTEGER;
      if (this.isCritical) {
        return aRelevance - bRelevance;
      } else {
        return aRelevance + bRelevance;
      }
    });

  }

}
