import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Input, OnChanges, OnInit, SimpleChanges } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatMenuModule } from '@angular/material/menu';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatExpansionModule } from '@angular/material/expansion';
import { MatDialog } from '@angular/material/dialog';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { HeaderService } from '../../../core/services/header/header.service';
import { CasedetailService } from '../../../shared/services/casedetail/casedetail.service';
import { CreateissueComponent } from '../../../realtime/components/issues/createissue/createissue.component';
import { WorkspaceChronologyComponent } from './workspace-chronology/workspace-chronology.component';
import { WorkspaceContactsComponent } from './workspace-contacts/workspace-contacts.component';
import { WorkspaceIssuesComponent } from './workspace-issues/workspace-issues.component';
import { WorkspaceOrganizeComponent } from './workspace-organize/workspace-organize.component';
import { WorkspaceService } from '../../services/workspace/workspace.service';
import { FiltersComponent } from '../../../shared/components/filters/filters.component';
import { toolEvents } from '../../../pdf/interfaces/pdf.interface';
import { 
  org_cols, 
  tablecols, 
  FilterOption, 
  IssueCategory, 
  IssueFilterOption, 
  RELEVANCE_OPTIONS, 
  COMPLETENESS_OPTIONS, 
  RELEVANCE_KEY_TO_ID,
  ORG_COLS,
  FACT_COLS,
  Q_FACT_COLS
} from '../../interfaces/workspace.interface';
import { CommunicationService } from '../../../shared/services/communication/communication.service';
import { Subject, debounceTime } from 'rxjs';
import { MatTooltipModule } from '@angular/material/tooltip';
import { UserPermissionService } from '../../../shared/services/user-permission/user-permission.service';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { ContactService } from '../../../shared/services/contact/contact.service';
import { TaskService } from '../../../shared/services/task/task.service';
import { IssueService } from '../../../rt/services/issue/issue.service';
import { CommonService } from '../../../shared/services/common/common.service';
import { TranslateModule, TranslateService } from '@ngx-translate/core';

@Component({
  selector: 'app-workspace',
  standalone: true,
  imports: [CommonModule, FormsModule, IconComponent, ButtonComponent, MatMenuModule, MatCheckboxModule, MatExpansionModule,
    WorkspaceChronologyComponent, WorkspaceContactsComponent, WorkspaceIssuesComponent, WorkspaceOrganizeComponent, FiltersComponent, MatTooltipModule, TranslateModule
  ],
  templateUrl: './workspace.component.html',
  styleUrl: './workspace.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class WorkspaceComponent implements OnInit, OnChanges {
    // Dynamic filter options for Type, Issue, Contact, Task
    typeOptions: FilterOption[] = [];
    issueCategories: IssueCategory[] = [];
    contactOptions: FilterOption[] = [];
    taskOptions: FilterOption[] = [];
    customIssueInput: string = '';

    get filteredIssueCategories() {
      if (!this.customIssueInput || this.customIssueInput.trim() === '') {
        return this.issueCategories;
      }
      const searchTerm = this.customIssueInput.toLowerCase();
      return this.issueCategories.map(cat => ({
        ...cat,
        issues: cat.issues.filter(opt => opt.label.toLowerCase().includes(searchTerm))
      })).filter(cat => cat.issues.length > 0);
    }

    get typeText(): string {
      const selected = this.typeOptions.filter(o => o.selected).map(o => o.label);
      return selected.length ? `${this.translate.instant('WORKSPACE.TYPE')} (${selected.length})` : this.translate.instant('WORKSPACE.TYPE_ANY');
    }
    get issueText(): string {
      const selectedCount = this.issueCategories.reduce((count, cat) => 
        count + cat.issues.filter(i => i.selected).length, 0
      );
      return selectedCount ? `${this.translate.instant('WORKSPACE.ISSUE')} (${selectedCount})` : this.translate.instant('WORKSPACE.ISSUE_ANY');
    }
    get contactText(): string {
      const selected = this.contactOptions.filter(o => o.selected).map(o => o.label);
      return selected.length ? `${this.translate.instant('WORKSPACE.CONTACT')} (${selected.length})` : this.translate.instant('WORKSPACE.CONTACT_ANY');
    }

    addCustomIssue() {
      if (this.customIssueInput?.trim()) {
        const customValue = this.customIssueInput.trim();
        // Check if already exists in any category
        let exists = false;
        for (const cat of this.issueCategories) {
          const found = cat.issues.find(o => o.label.toLowerCase() === customValue.toLowerCase());
          if (found) {
            found.selected = true;
            exists = true;
            break;
          }
        }
        if (!exists) {
          // Add new custom issue to "Custom" category
          let customCat = this.issueCategories.find(c => c.category === 'Custom');
          if (!customCat) {
            customCat = { category: 'Custom', issues: [] };
            this.issueCategories.push(customCat);
          }
          customCat.issues.push({
            key: customValue,
            label: customValue,
            color: '#6B7280',
            selected: true
          });
        }
        this.customIssueInput = '';
        this.applyAllFilters();
        this.cdr.detectChanges();
      }
    }

    toggleType(option: FilterOption) {
      this.toggleOption(option, () => this.applyAllFilters());
    }
    clearType() {
      this.typeOptions.forEach(o => (o.selected = false));
      this.applyAllFilters();
      this.cdr.detectChanges();
    }
    toggleIssue(option: IssueFilterOption) {
      this.toggleOption(option, () => this.applyAllFilters());
    }
    clearIssue() {
      this.issueCategories.forEach(cat => cat.issues.forEach(o => (o.selected = false)));
      this.customIssueInput = '';
      this.applyAllFilters();
      this.cdr.detectChanges();
    }
    toggleContact(option: FilterOption) {
      this.toggleOption(option, () => this.applyAllFilters());
    }
    clearContact() {
      this.contactOptions.forEach(o => (o.selected = false));
      this.applyAllFilters();
      this.cdr.detectChanges();
    }

    // Combine all filters and emit
    applyAllFilters() {
      console.log('DEBUG applyAllFilters: activetab =', this.activetab);
      const filterArray = this.buildFilterArray();
      console.log('DEBUG applyAllFilters: filterArray =', filterArray);
      // Emit filter to all tabs that support filtering, not just the active tab
      // This ensures contact/issue filters apply even when switching between tabs
      const tabsToUpdate = ["CH", "I", "O"];
      tabsToUpdate.forEach(tab => {
        this.emitFilterEvent(tab, filterArray);
      });
    }

    private buildFilterArray(): any[] {
      const filterArray = [];
      
      this.addImpactFilter(filterArray);
      this.addRelevanceFilter(filterArray);
      this.addTypeFilter(filterArray);
      this.addIssueFilter(filterArray);
      this.addContactFilter(filterArray);
      this.addSearchFilter(filterArray);
      this.addNoteSearchFilter(filterArray);
      this.addCompletenessFilter(filterArray);
      
      return filterArray;
    }

    private addImpactFilter(filterArray: any[]): void {
      const selectedImpacts = this.impactOptions.filter(o => o.selected).map(o => Number(o.key)).filter(id => !Number.isNaN(id));
      if (selectedImpacts.length) {
        filterArray.push({ name: 'IMPACT', type: 'V', value: selectedImpacts });
      }
    }

    private addRelevanceFilter(filterArray: any[]): void {
      const selectedRelevance = this.relevanceOptions.filter(o => o.selected).map(o => o.label).filter(label => !!label);
      if (selectedRelevance.length) {
        filterArray.push({ name: 'RELEVANCE', type: 'V', value: selectedRelevance });
      }
    }

    private addTypeFilter(filterArray: any[]): void {
      if (this.isFact) {
        const selectedTypes = this.typeOptions.filter(o => o.selected).map(o => o.key);
        if (selectedTypes.length) {
          filterArray.push({ name: 'TYPE', type: 'V', value: selectedTypes });
        }
      }
    }

    private addIssueFilter(filterArray: any[]): void {
      const selectedIssues = this.issueCategories
        .flatMap(cat => cat.issues)
        .filter(o => o.selected)
        .map(o => o.key);
      if (selectedIssues.length) {
        filterArray.push({ name: 'ISSUE', type: 'V', value: selectedIssues });
      }
    }

    private addContactFilter(filterArray: any[]): void {
      // Only apply contact filter when viewing Facts tab (not QFact)
      if (this.isFact) {
        const selectedContacts = this.contactOptions.filter(o => o.selected).map(o => o.key);
        if (selectedContacts.length) {
          filterArray.push({ name: 'CONTACT', type: 'V', value: selectedContacts });
        }
      }
    }

    private addSearchFilter(filterArray: any[]): void {
      if (this.searchText && this.searchText.trim().length > 0) {
        filterArray.push({ name: 'SEARCH', type: 'V', value: this.searchText.trim() });
      }
    }

    private addNoteSearchFilter(filterArray: any[]): void {
      if (this.noteSearchText && this.noteSearchText.trim().length > 0) {
        filterArray.push({ name: 'NOTE', type: 'V', value: this.noteSearchText.trim() });
      }
    }

    private addCompletenessFilter(filterArray: any[]): void {
      const selectedCompleteness = this.completenessOptions.filter(o => o.selected).map(o => o.key);
      if (selectedCompleteness.length) {
        filterArray.push({ name: 'COMPLETENESS', type: 'V', value: selectedCompleteness });
      }
    }

    noteSearchText: string = '';
    private readonly noteSearchSubject = new Subject<string>();
    
    setNoteSearchText(val: string) {
      this.noteSearchText = val;
      this.noteSearchSubject.next(val);
    }

    // Update searchText binding to use applyAllFilters
    setSearchText(val: string) {
      this.searchText = val;
      this.applyAllFilters();
      this.cdr.detectChanges();
    }
  relevanceKeyToId: { [key: string]: number } = RELEVANCE_KEY_TO_ID;
  nCaseid: string;
  showcolalert: boolean = false;
  activetab = 'CH';
  isFact: boolean = false;
  isQFact: boolean = true;
  isWithContact: boolean = true;
  isWithoutContact: boolean = true;
  @Input() nViewissueid: number = 0;
  showfilter: boolean = false;
  valueUpdateCH: Subject<toolEvents> = new Subject();
  valueUpdateC: Subject<toolEvents> = new Subject();
  valueUpdateI: Subject<toolEvents> = new Subject();
  valueUpdateO: Subject<toolEvents> = new Subject();

  // UI state for new fact workspace-style filters
  searchText: string = '';
  impactOptions: FilterOption[] = [];
  relevanceOptions: FilterOption[] = JSON.parse(JSON.stringify(RELEVANCE_OPTIONS));
  completenessOptions: FilterOption[] = JSON.parse(JSON.stringify(COMPLETENESS_OPTIONS));

  org_cols: org_cols[] = JSON.parse(JSON.stringify(ORG_COLS));
  org_cols_selected: string[];

  tablecols: tablecols[] = [];

  // Table column definitions aligned with new Fact workspace design
  factcols: tablecols[] = JSON.parse(JSON.stringify(FACT_COLS));
  Qfactcols: tablecols[] = JSON.parse(JSON.stringify(Q_FACT_COLS));

  organixeType: string = 'All';
  isFiltered: boolean = false;
  factlength: number[] = [];
  contactlength: number[] = [];
  isCritical: boolean = false;
  isHeavily: boolean = false;
  constructor(
    private readonly hs: HeaderService,
    private readonly cDetailS: CasedetailService,
    private readonly route: ActivatedRoute,
    private readonly cdr: ChangeDetectorRef,
    private readonly dialog: MatDialog,
    private readonly cs: CommunicationService,
    private readonly userPermissions: UserPermissionService,
    private readonly cf: CommonfunctionService,
    private readonly contactService: ContactService,
    private readonly taskService: TaskService,
    private readonly issueService: IssueService,
    private readonly common: CommonService,
    private readonly wsservice: WorkspaceService,
    private readonly translate: TranslateService
  ) {

    const params = JSON.parse(atob(this.route.snapshot.params["id"]));
    this.nCaseid = params?.id ?? 0;
    if (params?.tab) {
      this.activetab = params.tab || 'CH';
    }
  }

  ngOnInit(): void {
    // Load user permissions
    this.userPermissions.userPermissionList(this.nCaseid);
    
    // Set initial columns based on default tab (Q Fact)
    this.tablecols = this.isQFact ? this.Qfactcols : this.factcols;
    this.cdr.detectChanges();
    this.hs.nCaseid = this.nCaseid;

    // Setup debounced note search (300ms delay)
    this.noteSearchSubject.pipe(debounceTime(300)).subscribe(() => {
      this.applyAllFilters();
      this.cdr.detectChanges();
    });

    // Load dynamic dropdowns and case info in parallel
    this.initializeData();
  }

  private async initializeData(): Promise<void> {
    try {
      const [caseDetail] = await Promise.all([
        this.cDetailS.getCaseInfo(this.nCaseid),
        this.loadDropdownOptions()
      ]);

      this.hs.Casedetail = caseDetail;
      this.cdr.detectChanges();
    } catch (error) {
      console.error('Error initializing workspace component:', error);
      this.cdr.detectChanges();
    }
  }

  async loadDropdownOptions(): Promise<void> {
    try {
      // Get user info for issue API
      const userInfo: any = this.hs.userdetail || {};
      const nUserid = userInfo.nUserid || '';
      
      // Fetch all data in parallel
      const [impactList, types, contactCategories, tasks, issueData] = await Promise.all([
        this.common.getCode(5), // Impact
        this.common.getCode(23), // Type
        this.wsservice.getContactlist(this.nCaseid, []), // Contacts
        this.taskService.get_sidenavTask(this.nCaseid, []), // Tasks
        this.issueService.fetchIssueListV2({ 
          nCaseid: this.nCaseid, 
          nSessionid: 'null', 
          nIDid: 'null', 
          nUserid: nUserid 
        }) // Issues V2
      ]);
      
      // Extract issues from V2 response [categories, issues]
      const issues = issueData[1] || [];

      this.impactOptions = impactList.map(item => ({
        key: String(item.nValue),
        label: item.cKey,
        selected: false
      }));

      this.typeOptions = types.map(t => ({
        key: t.cKey,
        label: t.cKey,
        selected: false
      }));

      const allContacts = contactCategories.flatMap(cat => cat.contactls || []);
      this.contactOptions = allContacts.map(c => ({
        key: c.cEmail || c.nContactid,  // Use email as key since backend returns jContactEmails
        label: `${c.cFname || ''} ${c.cLname || ''}`.trim(),
        selected: false
      }));

      this.taskOptions = tasks.map(t => ({
        key: t.nTaskid || t.cKey || t.cTaskName,
        label: t.cTaskName || t.cKey,
        selected: false
      }));

      // Group issues by category
      const categories = issueData[0] || [];
      const categoryMap = new Map(categories.map((c: any) => [c.nICid, c.cCategory]));
      
      // Group issues by their category
      const issuesByCategory = new Map<string, any[]>();
      issues.forEach(issue => {
        const catName = categoryMap.get(issue.nICid) || 'Uncategorized';
        if (!issuesByCategory.has(catName)) {
          issuesByCategory.set(catName, []);
        }
        const categoryIssues = issuesByCategory.get(catName);
        if (categoryIssues) {
          categoryIssues.push(issue);
        }
      });
      
      // Convert to issueCategories structure
      this.issueCategories = Array.from(issuesByCategory.entries()).map(([category, catIssues]) => ({
        category,
        issues: catIssues.map(i => ({
          key: i.nIid,
          label: i.cIName,
          color: (i.cColor && !i.cColor.startsWith('#') ? '#' + i.cColor : i.cColor) || '#6B7280',
          selected: false
        }))
      })).sort((a, b) => a.category.localeCompare(b.category));

      this.cdr.detectChanges();
    } catch (error) {
      console.error('Error loading dropdown options:', error);
      // Initialize with empty arrays on error
      this.impactOptions = [];
      this.typeOptions = [];
      this.contactOptions = [];
      this.taskOptions = [];
      this.issueCategories = [];
      this.cdr.detectChanges();
    }
  }
  
  ngOnChanges(changes: SimpleChanges): void {
    //Called before any other lifecycle hook. Use it to inject dependencies, but avoid any serious work here.
    //Add '${implements OnChanges}' to the class.
    this.changeOrganizeDisplay();
  }


  navInNewTab(x) {
    window.open(`${location.origin}/myfiles/workspace/${btoa(JSON.stringify({ id: this.nCaseid, tab: this.activetab }))}`);
  }

  changeTab(x) {
    this.activetab = x.tab;
    this.cdr.detectChanges()
  }

  changeTabcols(x) {
    if (x.isshow === true && this.tablecols.filter(x => x.isshow === true).length <= 3) { this.showcolalert = true; return }
    x.isshow = !x.isshow;
    this.showcolalert = false;
    this.cs.callFunction({ type: 'SHOW-COLS', tablecols: this.tablecols });
  }

  changeQFactCols(col: tablecols) {
    // Enforce minimum of 3 visible columns for Q Fact tab
    if (col.isshow && this.Qfactcols.filter(c => c.isshow).length <= 3) {
      this.showcolalert = true;
      return;
    }

    col.isshow = !col.isshow;
    this.showcolalert = false;

    // If Q Fact view is currently active, propagate to table and children
    if (!this.isFact) {
      this.tablecols = this.Qfactcols;
      this.cs.callFunction({ type: 'SHOW-COLS', tablecols: this.tablecols });
    }
    this.cdr.detectChanges();
  }

  changeFactCols(col: tablecols) {
    // Enforce minimum of 3 visible columns for Fact tab
    if (col.isshow && this.factcols.filter(c => c.isshow).length <= 3) {
      this.showcolalert = true;
      return;
    }

    col.isshow = !col.isshow;
    this.showcolalert = false;

    // If Fact view is currently active, propagate to table and children
    if (this.isFact) {
      this.tablecols = this.factcols;
      this.cs.callFunction({ type: 'SHOW-COLS', tablecols: this.tablecols });
    }
    this.cdr.detectChanges();
  }


  createIssue(x?) {
    const dialog = this.dialog.open(CreateissueComponent, {
      width: '750px',
      height: 'fit-content',
      hasBackdrop: true,
      panelClass: 'noshadow',
      data: { type: x ? 'E' : null, value: x || null, current_session: { nCaseid: this.nCaseid } },
    });
    dialog.componentInstance.isCentered = true;
    dialog.afterClosed().subscribe((result) => {
      this.cdr.detectChanges();
    })
  }

  OnFilterResult(e: toolEvents) {

    if (e.event === 'FILTER') {
      this.emitFilterEvent(this.activetab, e.data);
      this.isFiltered = e.data?.length;
      this.cdr.detectChanges();
    } else if (e.event === 'BACK') {
      this.showfilter = false;
      this.cdr.detectChanges();
    }
  }

  OnDataEvent(e: toolEvents) {
    if (e.event === 'EXTERNAL-FACT-SHEET') {
      this.openFactLink(e.data);
    }
    if (e.event === 'Length') {
      if (this.activetab === 'C') {
        this.contactlength = e.data
      } else {
        this.factlength = e.data;
      }
    }
    this.cdr.detectChanges();
  }

  openFactLink(data) {
    if (!data.nBundledetailid) return;
    const nPage = data.nPage || 1;
    this.cf.openHyperLinkFile(data.nBundledetailid, this.nCaseid, null, null, false, nPage, this.isFact ? data.nFSid : null, this.isFact ? null : data.nFSid
    );

  }

  changeOrganizeDisplay() {
    if (this.organixeType === 'L') {
      this.org_cols_selected = this.org_cols.filter(x => x.isselect).map(x => x.key);
      this.cdr.detectChanges();
    }
  }


  resetTable() {
    this.tablecols.forEach(x => x.isshow = true);
    this.cs.callFunction({ type: 'SHOW-COLS', tablecols: this.tablecols });
  }


  factchange(flag) {
    this.isFact = flag === 'F';
    this.isQFact = flag === 'Q';

    if (this.isFact) {
      this.tablecols = this.factcols;
    }
    else {
      this.tablecols = this.Qfactcols;
    }

  }

  get impactText(): string {
    const selected = this.impactOptions.filter(o => o.selected).map(o => o.label);
    return selected.length ? `${this.translate.instant('WORKSPACE.IMPACT')} (${selected.length})` : this.translate.instant('WORKSPACE.IMPACT_ANY');
  }

  get relevanceText(): string {
    const selected = this.relevanceOptions.filter(o => o.selected).map(o => o.label);
    return selected.length ? `${this.translate.instant('WORKSPACE.RELEVANCE')} (${selected.length})` : this.translate.instant('WORKSPACE.RELEVANCE_ANY');
  }


  toggleImpact(option: FilterOption) {
    this.toggleOption(option, () => this.applyImpactRelevanceFilter());
  }


  clearImpact() {
    this.impactOptions.forEach(o => (o.selected = false));
    this.applyImpactRelevanceFilter();
    this.cdr.detectChanges();
  }


  toggleRelevance(option: FilterOption) {
    this.toggleOption(option, () => this.applyImpactRelevanceFilter());
  }


  clearRelevance() {
    this.relevanceOptions.forEach(o => (o.selected = false));
    this.applyImpactRelevanceFilter();
    this.cdr.detectChanges();
  }
  // --- New method to emit filter event for impact/relevance ---
  applyImpactRelevanceFilter() {
    const selectedImpacts = this.impactOptions
      .filter(o => o.selected)
      .map(o => Number(o.key)) // Use the nValue directly
      .filter(id => !Number.isNaN(id));
    const selectedRelevance = this.relevanceOptions
      .filter(o => o.selected)
      .map(o => o.label)
      .filter(label => !!label);
    const filterArray = [];
    if (selectedImpacts.length) {
      filterArray.push({ name: 'IMPACT', type: 'V', value: selectedImpacts });
    }
    if (selectedRelevance.length) {
      filterArray.push({ name: 'RELEVANCE', type: 'V', value: selectedRelevance });
    }
    if (this.searchText && this.searchText.trim().length > 0) {
      filterArray.push({ name: 'SEARCH', type: 'V', value: this.searchText.trim() });
    }
    // Only send filter event for tabs that display facts (not contacts)
    if (['CH', 'I', 'O'].includes(this.activetab)) {
      this.emitFilterEvent(this.activetab, filterArray);
    }
  }

  // Helper method to emit filter events for different tabs
  private emitFilterEvent(tab: string, data: any): void {
    const event: toolEvents = { event: 'FILTER', data };
    switch (tab) {
      case 'CH':
        this.valueUpdateCH.next(event);
        break;
      case 'I':
        this.valueUpdateI.next(event);
        break;
      case 'O':
        this.valueUpdateO.next(event);
        break;
    }
  }

  toggleCompleteness(option: FilterOption) {
    this.toggleOption(option, () => this.applyAllFilters());
  }

  clearCompleteness() {
    this.completenessOptions.forEach(o => (o.selected = false));
    this.applyAllFilters();
    this.cdr.detectChanges();
  }

  resetFilters() {
    this.searchText = '';
    this.noteSearchText = '';
    this.clearImpact();
    this.clearRelevance();
    this.clearType();
    this.clearIssue();
    this.clearContact();
    this.completenessOptions.forEach(o => (o.selected = false));
    this.cdr.detectChanges();
  }

  // Generic method to toggle options and apply filters
  private toggleOption(option: { selected: boolean }, applyFilter: () => void): void {
    option.selected = !option.selected;
    applyFilter();
    this.cdr.detectChanges();
  }

}
